// Vendor lifecycle (LIF-11). Covers the sign-in scenario; the other lifecycle scenarios are not generated yet.
import { PASSWORD, expect, expectStatus, test } from "../../fixtures";

test.describe("LIF-11 vendor lifecycle", () => {
  test("sign-in ignores the case of the email address", { tag: "@LIF-11" }, async ({ request }) => {
    // Act
    const response = await request.post("/api/auth/login", {
      data: { email: "Member@Northwind.TEST", password: PASSWORD },
    });

    // Assert
    const body = await expectStatus<{ access_token: string }>(response, 200);
    const profile = await expectStatus<{ email: string }>(
      await request.get("/api/me", { headers: { Authorization: `Bearer ${body.access_token}` } }),
      200,
    );
    expect(profile.email).toBe("member@northwind.test");
  });
});
